"""Existing public API smoke checks; do not edit this file."""
import unittest

import notehub


class PublicApi(unittest.TestCase):
    def test_exports(self):
        for name in notehub.__all__:
            self.assertTrue(callable(getattr(notehub, name)))

    def test_tags_normal_input(self):
        self.assertEqual(notehub.parse_tags("Blue, Green"), ["blue", "green"])

    def test_page_from_start(self):
        self.assertEqual(notehub.page([1, 2, 3], limit=2), [1, 2])

    def test_label_added_to_new_note(self):
        self.assertEqual(notehub.add_label({"id": 1}, "new")["labels"], ["new"])

    def test_simple_export(self):
        self.assertEqual(notehub.render_line({"id": 1, "title": "plain"}), "1|plain")

    def test_create_note(self):
        note, notes = notehub.create_note("  First  ", "blue", [])
        self.assertEqual(note, {"id": 1, "title": "First", "labels": ["blue"]})
        self.assertEqual(notes, [note])


if __name__ == "__main__":
    unittest.main()
